use std::fmt::Write as _;
use std::path::Path;

use crate::codegen::model::{FieldType, ServiceDef};
use crate::codegen::type_map::expand_wasm;

/// Generate `{out_dir}/{service_name}_wasm_bindings.rs`.
///
/// The generated file contains `impl HostModule for {ModuleName}` and is
/// `include!`ed from the executor's source file. Everything else (the
/// `HostModule` trait, `WasmCtx`, the surrounding struct) stays handwritten.
pub fn generate(service: &ServiceDef, out_dir: &Path) {
    let module_struct = capitalize(&service.name) + "Module";
    let out_path = out_dir.join(format!("{}_wasm_bindings.rs", service.name));

    let mut buf = String::new();
    writeln!(
        buf,
        "// AUTO-GENERATED by build/codegen/rust_wasm.rs — DO NOT EDIT."
    )
    .unwrap();
    writeln!(buf, "// Source: src/{}/ @wasm annotations", service.name).unwrap();
    writeln!(buf).unwrap();

    writeln!(buf, "use crate::drawer::*;").unwrap();
    writeln!(buf).unwrap();

    // Determine the WASM module name (all bindings in one service share the same module)
    let wasm_module = service
        .bindings
        .first()
        .map(|b| b.wasm_module.as_str())
        .unwrap_or("env");

    writeln!(buf, "impl HostModule for {module_struct} {{").unwrap();
    writeln!(buf, "    fn name(&self) -> &str {{ \"{wasm_module}\" }}").unwrap();
    writeln!(buf).unwrap();
    writeln!(buf, "    fn register(").unwrap();
    writeln!(buf, "        &self,").unwrap();
    writeln!(buf, "        linker: &mut Linker<WasmCtx>,").unwrap();
    writeln!(buf, "        store: &mut Store<WasmCtx>,").unwrap();
    writeln!(buf, "    ) -> Result<(), wasmi::Error> {{").unwrap();

    for binding in &service.bindings {
        writeln!(buf).unwrap();
        writeln!(buf, "        // --- {} ---", binding.wasm_fn).unwrap();

        // Collect all flat WASM params across all fields
        let mut all_params: Vec<String> = Vec::new();
        let mut has_str_field = false;
        for field in &binding.fields {
            let exp = expand_wasm(&field.name, &field.ty);
            all_params.extend(exp.params);
            if field.ty == FieldType::Str {
                has_str_field = true;
            }
        }

        let param_list = all_params
            .iter()
            .map(|p| format!("{p}: u32"))
            .collect::<Vec<_>>()
            .join(", ");

        writeln!(buf, "        linker.define(").unwrap();
        writeln!(buf, "            self.name(),").unwrap();
        writeln!(buf, "            \"{}\",", binding.wasm_fn).unwrap();
        writeln!(buf, "            wasmi::Func::wrap(").unwrap();
        writeln!(buf, "                &mut *store,").unwrap();
        writeln!(
            buf,
            "                |mut caller: Caller<'_, WasmCtx>{sep}{param_list}| {{",
            sep = if all_params.is_empty() { "" } else { ", " },
        )
        .unwrap();

        // Memory extraction for str fields
        if has_str_field {
            emit_str_preamble(&mut buf, &binding.fields);
        }

        // Construct the *Data struct
        if !binding.fields.is_empty() {
            writeln!(
                buf,
                "                    let data = {} {{",
                binding.data_type
            )
            .unwrap();
            for field in &binding.fields {
                let exp = expand_wasm(&field.name, &field.ty);
                let construct = if field.ty == FieldType::Str {
                    format!("&*{}_buf", field.name)
                } else {
                    exp.construct
                };
                writeln!(buf, "                        {}: {construct},", field.name).unwrap();
            }
            writeln!(buf, "                    }};").unwrap();
            writeln!(
                buf,
                "                    caller.data_mut().{}().{}(data);",
                service.name, binding.executor_method
            )
            .unwrap();
        } else {
            writeln!(
                buf,
                "                    caller.data_mut().{}().{}();",
                service.name, binding.executor_method
            )
            .unwrap();
        }

        writeln!(buf, "                }},").unwrap();
        writeln!(buf, "            ),").unwrap();
        writeln!(buf, "        )?;").unwrap();
    }

    writeln!(buf).unwrap();
    writeln!(buf, "        Ok(())").unwrap();
    writeln!(buf, "    }}").unwrap();
    writeln!(buf, "}}").unwrap();

    std::fs::write(&out_path, &buf)
        .unwrap_or_else(|e| panic!("cannot write {}: {e}", out_path.display()));
}

/// Emit the heapless memory-read preamble for every Str field in the binding.
fn emit_str_preamble(buf: &mut String, fields: &[crate::codegen::model::FieldDef]) {
    for field in fields {
        if field.ty != FieldType::Str {
            continue;
        }
        let n = &field.name;
        writeln!(
            buf,
            "                    let memory = match caller.get_export(\"memory\") {{"
        )
        .unwrap();
        writeln!(
            buf,
            "                        Some(wasmi::Extern::Memory(m)) => m,"
        )
        .unwrap();
        writeln!(buf, "                        _ => return,").unwrap();
        writeln!(buf, "                    }};").unwrap();
        writeln!(buf, "                    let {n}_start = {n}_ptr as usize;").unwrap();
        writeln!(
            buf,
            "                    let {n}_end = {n}_start + {n}_len as usize;"
        )
        .unwrap();
        writeln!(
            buf,
            "                    let memory_data = memory.data(&caller);"
        )
        .unwrap();
        writeln!(
            buf,
            "                    if {n}_end > memory_data.len() {{ return; }}"
        )
        .unwrap();
        writeln!(
            buf,
            "                    let {n}_bytes = match memory_data.get({n}_start..{n}_end) {{"
        )
        .unwrap();
        writeln!(buf, "                        Some(b) => b,").unwrap();
        writeln!(buf, "                        None => return,").unwrap();
        writeln!(buf, "                    }};").unwrap();
        writeln!(
            buf,
            "                    let {n}_utf8 = match core::str::from_utf8({n}_bytes) {{"
        )
        .unwrap();
        writeln!(buf, "                        Ok(s) => s,").unwrap();
        writeln!(buf, "                        Err(_) => return,").unwrap();
        writeln!(buf, "                    }};").unwrap();
        writeln!(
            buf,
            "                    let mut {n}_buf = heapless::String::<256>::new();"
        )
        .unwrap();
        writeln!(
            buf,
            "                    if {n}_buf.push_str({n}_utf8).is_err() {{ return; }}"
        )
        .unwrap();
    }
}

fn capitalize(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        None => String::new(),
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
    }
}
